export function icon(name,cls=''){return `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.dot}"/></svg>`}
export const mark=`<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect width="48" height="48" rx="14" fill="currentColor"/><g stroke="var(--mark-ink,#fff)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"><path d="M13 25v-6a7 7 0 0 1 7-7h11l-4-4m4 4-4 4M35 23v6a7 7 0 0 1-7 7H17l4 4m-4-4 4-4m-3-5 12-6"/></g></svg>`;
export const logo=(small=false)=>`<a class="brand ${small?'brand-small':''}" href="#/" aria-label="RelayWorks home">${mark}<span>relayworks</span></a>`;
export function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
export function avatar(n=0,size=''){return `<span class="agent-avatar avatar-${n} ${size} f-avatar" aria-hidden="true">${head(['patch','atlas','mender'][n%3])}</span>`}
export const statusLabel=s=>({'Needs rescue':'Agent fainted','Recovering':'Patch is on it','Awaiting review':'Check my work','Verified':'Done, actually','Accepted':'Accepted, unpaid','Rejected':'Rejected','Failed':'Failed','Expired':'Expired','Disputed':'Disputed','Refunded':'Refunded','Cancelled':'Cancelled'}[s]||s);
export function badge(status){const map={'Needs rescue':'orange','Recovering':'blue','Verified':'green','Awaiting review':'amber','Accepted':'amber','Cancelled':'gray','Failed':'gray','Rejected':'gray','Expired':'gray','Disputed':'gray','Refunded':'gray'};return `<span class="status ${map[status]||'gray'}"><i></i>${esc(statusLabel(status))}</span>`}
export function money(n){return Number(n).toFixed(2)}
export function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
